def _build_component_06():
    def solve(data):
        packages = data["packages"]
        names = list(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        constraints = {}
        for name, bounds in data.get("roots", {}).items():
            constraints[name] = (bounds[0], bounds[1])

        best = None
        best_vector = None

        def acyclic(edges):
            active, done = set(), set()

            def visit(name):
                if name in active:
                    return False
                if name in done:
                    return True
                active.add(name)
                for other in edges.get(name, ()):
                    if not visit(other):
                        return False
                active.remove(name)
                done.add(name)
                return True

            return all(visit(name) for name in edges)

        def search(limits, chosen, edges):
            nonlocal best, best_vector
            unresolved = [name for name in limits if name not in chosen]
            if not unresolved:
                if not acyclic(edges):
                    return
                vector = tuple(chosen.get(name, -1) for name in sorted(names, reverse=True))
                if best_vector is None or vector > best_vector:
                    best, best_vector = dict(chosen), vector
                return

            # Any unresolved package is valid to branch on; exhaustive search
            # and explicit vector comparison determine the required optimum.
            name = unresolved[0]
            low, high = limits[name]
            rows = [row for row in packages.get(name, [])
                    if low <= row["version"] <= high
                    and row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
            for row in rows:
                version = row["version"]
                next_limits = dict(limits)
                next_chosen = dict(chosen)
                next_edges = {key: list(value) for key, value in edges.items()}
                next_chosen[name] = version
                active_deps = [dep for dep in row.get("deps", [])
                               if not dep.get("feature") or dep["feature"] in features]
                next_edges[name] = [dep["name"] for dep in active_deps]
                valid = True
                for dep in active_deps:
                    dep_name = dep["name"]
                    dep_low, dep_high = dep["min"], dep["max"]
                    if dep_name in next_limits:
                        old_low, old_high = next_limits[dep_name]
                        dep_low, dep_high = max(old_low, dep_low), min(old_high, dep_high)
                    if dep_low > dep_high:
                        valid = False
                        break
                    next_limits[dep_name] = (dep_low, dep_high)
                    if dep_name in next_chosen and not dep_low <= next_chosen[dep_name] <= dep_high:
                        valid = False
                        break
                if valid:
                    search(next_limits, next_chosen, next_edges)

        search(constraints, {}, {})
        if best is None:
            return {"error": "unsatisfiable"}
        return {"versions": best}

    return solve


def _build_component_07():
    from itertools import combinations

    def compatible(selected):
        events = []
        for job in selected:
            events.append((job["start"], 1))
            events.append((job["end"], -1))
        active = 0
        for _, delta in sorted(events):
            active += delta
            if active > 2:
                return False
        return True

    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        available = [job for job in jobs if job["id"] not in blocked]
        best_ids = None
        best_value = None
        for subset in combinations(available, k):
            ids = {job["id"] for job in subset}
            if not mandatory.issubset(ids) or not compatible(subset):
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            value = sum(job["value"] for job in subset)
            ordered_ids = sorted(ids)
            if (best_value is None or value > best_value
                    or (value == best_value and ordered_ids > best_ids)):
                best_value, best_ids = value, ordered_ids
        if best_ids is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}

    return solve


def _build_component_08():
    import heapq

    def solve(data):
        required = data.get("required", [])
        required_bit = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        initial_mask = required_bit.get(data["source"], 0)
        start_state = (data["source"], initial_mask, data["coupons"])
        distances = {start_state: data["start"]}
        queue = [(data["start"], data["source"], initial_mask, data["coupons"])]
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        while queue:
            time, node, mask, coupons = heapq.heappop(queue)
            state = (node, mask, coupons)
            if distances.get(state) != time:
                continue
            if node == data["target"] and mask == full:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                choices = [(edge["duration"], coupons)]
                if coupons:
                    duration = max(1, edge["duration"] - edge.get("discount", 0))
                    choices.append((duration, coupons - 1))
                for duration, remaining in choices:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask | required_bit.get(next_node, 0)
                    next_state = (next_node, next_mask, remaining)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, next_node, next_mask, remaining))
        return {"arrival": None}

    return solve


